<form method="post" action="<?= base_url(isset($item['id']) ? 'items/update/' . $item['id'] : 'items/store') ?>" class="card card-body">
    <div class="row"><div class="col-md-4 mb-3"><label class="form-label">Kode</label><input type="text" name="code" class="form-control" value="<?= e($item['code'] ?? '') ?>" required></div><div class="col-md-8 mb-3"><label class="form-label">Nama</label><input type="text" name="name" class="form-control" value="<?= e($item['name'] ?? '') ?>" required></div></div>
    <div class="row"><div class="col-md-6 mb-3"><label class="form-label">Kategori</label><select name="category_id" class="form-select"><option value="">Tanpa kategori</option><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>" <?= (string) ($item['category_id'] ?? '') === (string) $category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3 mb-3"><label class="form-label">Jumlah</label><input type="number" name="quantity" min="0" class="form-control" value="<?= e($item['quantity'] ?? 0) ?>"></div><div class="col-md-3 mb-3"><label class="form-label">Satuan</label><input type="text" name="unit" class="form-control" value="<?= e($item['unit'] ?? 'unit') ?>"></div></div>
    <div class="row"><div class="col-md-4 mb-3"><label class="form-label">Harga</label><input type="number" name="price" min="0" step="0.01" class="form-control" value="<?= e($item['price'] ?? 0) ?>"></div><div class="col-md-4 mb-3"><label class="form-label">Tanggal Masuk</label><input type="date" name="entry_date" class="form-control" value="<?= e($item['entry_date'] ?? '') ?>"></div></div>
    <div class="mb-3"><label class="form-label">Deskripsi</label><textarea name="description" class="form-control" rows="4"><?= e($item['description'] ?? '') ?></textarea></div>
    <div><button class="btn btn-primary">Simpan</button> <a href="<?= base_url('items') ?>" class="btn btn-secondary">Batal</a></div>
</form>
